const page=document.body.dataset.page;
const nav=[['Home','index.html','home'],['Visual Journey','visual-journey.html','visual'],['Idea Presentation','idea-presentation.html','idea'],['Working Log','working-log.html','log'],['[Project Title]','project.html','project'],['Feedback','feedback.html','feedback'],['About','about.html','about']];
const header=`<header class="site-head"><a class="brand" href="index.html">AI / <span>WF</span> / MEDIA</a><nav class="nav" aria-label="Primary">${nav.map(([label,href,id])=>`<a href="${href}" ${page===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav></header><div class="ticker" aria-hidden="true"><span>PROCESS IS THE PROJECT · IMAGE / TEXT / SOUND / FAILURE / REVISION · PROCESS IS THE PROJECT · IMAGE / TEXT / SOUND / FAILURE / REVISION · </span></div>`;
const footer=`<footer><span>AI Workflow for Media / Final Project Archive</span><span>Built as an evolving record — 2026</span></footer>`;
const intro=(title,kicker,desc,color='')=>`<section class="page-intro"><h1>${title}</h1><aside class="${color}"><span class="eyebrow">${kicker}</span><p>${desc}</p><span class="stamp">Living archive<br>v.01</span></aside></section>`;
const pages={
home:`<main><section class="home-stage"><div class="hero-copy"><span class="eyebrow">Final Project Process Archive / AI Workflow for Media</span><h1>Make<br><i>Visible</i><br>The Process</h1><div class="hero-meta"><div><b>Identity</b><br>AI, image, motion & authorship</div><div><b>Current focus</b><br>Prototype → test → revise</div><div><b>Status</b><br>In active development</div></div></div><div class="signal-board" aria-label="Interactive signal board"><button class="signal signal-a" aria-label="Trigger camera glitch"><span>01 / Look</span></button><button class="signal signal-b" aria-label="Trigger camera glitch"><span>02 / Break</span></button><button class="signal signal-c" aria-label="Trigger camera glitch"><span>03 / Rebuild</span></button><p class="glitch-hint">CLICK A SIGNAL → 1 SECOND CAMERA GLITCH</p></div></section><section class="content-grid"><article class="block span-8"><span class="eyebrow">Project identity</span><h2>A trace of decisions, not a clean retrospective.</h2><p>This site follows a media project from first reference to final form. Notes, failed tests and revisions remain visible so the work can be read as a system of choices.</p></article><article class="block span-4 black"><span class="number">03</span><h2>Selected highlights</h2><p>Reference mapping<br>Visual experiments<br>Final presentation</p></article></section></main>`,
visual:`<main>${intro('Visual<br>Journey','References / Annotations / Sources','A personal constellation of images, films, websites and documents. Image references resist the cursor; everything else remains openable.')}<section class="ref-toolbar"><div><b>YOUR REFERENCE ARCHIVE</b><br><small>Stored locally in this browser. Nothing is uploaded to a server.</small></div><button class="upload-btn" id="open-upload">+ Add reference</button></section><section class="reference-grid" id="reference-grid"></section></main>`,
idea:`<main>${intro('Idea<br>Presentation','Project proposal','A working proposition: how can AI become visible as a material process rather than disappear behind a finished image?','orange')}<article class="proposal"><span class="eyebrow">Proposal / 01</span><h2>The machine leaves a trace.</h2><p class="manifesto">This project treats prompts, selections, errors, iterations and human intervention as visible material. The final work will not hide the workflow; it will make the workflow the subject.</p><ul class="list"><li><b>Question</b><span>What changes when the audience can see how the image was negotiated?</span></li><li><b>Method</b><span>Collect → generate → annotate → distort → compare → revise.</span></li><li><b>Outcome</b><span>A time-based media work and a transparent process archive.</span></li></ul></article></main>`,
log:`<main>${intro('Working<br>Log','Development record','Dated notes, experiments, technical tests, failures, revisions and decisions — kept in chronological tension.','black')}<section><article class="log-entry"><time>2026—09—21</time><div><strong>System definition</strong><p>Mapped the archive into seven independent routes. Established a visual grammar of hard edges, offset blocks and high-contrast signals.</p></div><span class="tag">Decision</span></article><article class="log-entry"><time>2026—09—18</time><div><strong>Interaction test</strong><p>Tested evasive reference images: the visual source stays present but refuses capture, turning browsing into a physical negotiation.</p></div><span class="tag">Experiment</span></article><article class="log-entry"><time>2026—09—12</time><div><strong>First failure</strong><p>The initial output was too polished and concealed its own construction. Noise, timestamps and annotations were reintroduced.</p></div><span class="tag">Revision</span></article></section></main>`,
project:`<main>${intro('[Project]<br>Title','Final project showcase','Replace the working title and placeholder material when the final media piece is ready.')}<section class="showcase"><div class="project-void" aria-label="Animated project placeholder"><div class="orbit"></div></div><article class="project-copy"><span class="eyebrow">Final outcome / Coming into focus</span><h2>The final work belongs here.</h2><p>Use this page for the finished film, installation, interactive work or image sequence. Pair the artifact with a concise statement, credits and viewing conditions.</p><p><b>Format</b><br>Moving image / interactive media</p><p><b>Status</b><br>In development</p></article></section></main>`,
feedback:`<main>${intro('Feedback<br>→ Revision','Audience response','A record of what people noticed, what changed, and which suggestions were deliberately left unresolved.','violet')}<section><article class="feedback-card"><b>01</b><div><span class="eyebrow">Observation</span><h2>“The process is more compelling than the result.”</h2><p><strong>Resulting revision:</strong> expanded the working log and connected each decision to a visible experiment.</p></div></article><article class="feedback-card"><b>02</b><div><span class="eyebrow">Question</span><h2>“Where does your authorship sit?”</h2><p><strong>Resulting revision:</strong> added selection criteria and disclosed where generative tools entered the workflow.</p></div></article></section></main>`,
about:`<main>${intro('About','Author / Role / Contact','A concise biography and a transparent account of how AI participated in the project.','black')}<section class="about-layout"><div class="portrait-symbol" aria-label="Abstract portrait placeholder"><div></div></div><article class="about-copy"><span class="eyebrow">Author</span><h2>Your Name</h2><p>I work across moving image, visual systems and experimental interfaces. I am interested in the point where a tool stops being invisible and starts shaping the story.</p><ul class="list"><li><b>Role</b><span>Creative direction / research / production</span></li><li><b>Interests</b><span>AI image-making, archives, cinematic space, interaction</span></li><li><b>Contact</b><span><a href="mailto:your.name@example.com">your.name@example.com</a></span></li></ul><h3>Transparent AI-use statement</h3><p>AI tools support ideation, visual experimentation and selected production tasks. All prompts, outputs, edits and curatorial decisions are documented. The author remains responsible for concept, selection, context and final presentation.</p></article></section></main>`
};
document.querySelector('#site').innerHTML=header+(pages[page]||pages.home)+footer;

function cameraGlitch(){
  const overlay=document.createElement('div'); overlay.className='glitch-overlay'; overlay.innerHTML='<video autoplay muted playsinline></video><div class="glitch-text">SIGNAL<br>INTERRUPTED</div>'; document.body.append(overlay);
  const video=overlay.querySelector('video'); let stream;
  navigator.mediaDevices?.getUserMedia({video:{facingMode:'user'},audio:false}).then(s=>{stream=s;video.srcObject=s}).catch(()=>{video.style.display='none';overlay.querySelector('.glitch-text').innerHTML='CAMERA<br>UNAVAILABLE'});
  setTimeout(()=>{stream?.getTracks().forEach(t=>t.stop());overlay.remove()},1000);
}
document.querySelectorAll('.signal').forEach(el=>el.addEventListener('click',cameraGlitch));

const DB='ai-workflow-references',STORE='references';
function dbOpen(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE,{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function allRefs(){const db=await dbOpen();return new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>b.created-a.created));r.onerror=()=>reject(r.error)})}
async function putRef(ref){const db=await dbOpen();return new Promise((resolve,reject)=>{const r=db.transaction(STORE,'readwrite').objectStore(STORE).put(ref);r.onsuccess=resolve;r.onerror=()=>reject(r.error)})}
function escapeImage(el){let tx=0,ty=0;const reset=()=>{tx=0;ty=0;el.style.transform='translate(0,0) rotate(0)'};el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.hypot(dx,dy)||1;tx-=dx/m*95;ty-=dy/m*75;tx=Math.max(-125,Math.min(125,tx));ty=Math.max(-90,Math.min(90,ty));el.style.transform=`translate(${tx}px,${ty}px) rotate(${dx>0?-4:4}deg)`});el.addEventListener('pointerleave',reset);el.addEventListener('click',e=>e.preventDefault())}
async function renderRefs(){const grid=document.querySelector('#reference-grid');if(!grid)return;const refs=await allRefs();if(!refs.length){grid.innerHTML='<div class="empty"><div><div class="number">00</div><h2>NO REFERENCES YET</h2><p>Add an image, video, website link or file to begin the visual constellation.</p></div></div>';return}grid.innerHTML=refs.map(r=>{let preview;if(r.kind==='image')preview=`<a class="ref-preview image-escape" href="#" aria-label="Evasive image: ${r.title}"><img src="${URL.createObjectURL(r.file)}" alt="${r.title}"></a>`;else if(r.kind==='video')preview=`<div class="ref-preview"><video src="${URL.createObjectURL(r.file)}" controls></video></div>`;else if(r.kind==='link')preview=`<a class="ref-preview" href="${r.url}" target="_blank" rel="noreferrer">OPEN WEBSITE ↗</a>`;else preview=`<a class="ref-preview" href="${URL.createObjectURL(r.file)}" download="${r.file.name}">DOWNLOAD FILE ↓</a>`;return `<article class="ref-card"><span class="eyebrow">${r.kind}</span><h3>${r.title}</h3>${preview}<p>${r.notes||''}</p><div class="ref-meta"><span>${new Date(r.created).toLocaleDateString()}</span><span>Source / Personal archive</span></div></article>`}).join('');grid.querySelectorAll('.image-escape').forEach(escapeImage)}
if(page==='visual'){
  const dialog=document.createElement('dialog');dialog.className='dialog';dialog.innerHTML=`<div class="dialog-head"><span>Add reference</span><button class="icon-btn" aria-label="Close">×</button></div><form class="form" id="ref-form"><div class="field"><label for="ref-kind">Format</label><select id="ref-kind" name="kind"><option value="image">Image</option><option value="video">Video</option><option value="link">Website link</option><option value="file">File</option></select></div><div class="field"><label for="ref-title">Title</label><input id="ref-title" name="title" required placeholder="Reference title"></div><div class="field file-field"><label for="ref-file">Choose file</label><input id="ref-file" name="file" type="file" accept="image/*"></div><div class="field url-field" hidden><label for="ref-url">Website URL</label><input id="ref-url" name="url" type="url" placeholder="https://"></div><div class="field"><label for="ref-notes">Annotation / personal response</label><textarea id="ref-notes" name="notes" placeholder="What does this reference unlock?"></textarea></div><button class="primary" type="submit">Save to archive</button></form>`;document.body.append(dialog);
  const kind=dialog.querySelector('#ref-kind'),fileWrap=dialog.querySelector('.file-field'),urlWrap=dialog.querySelector('.url-field'),file=dialog.querySelector('#ref-file');
  kind.addEventListener('change',()=>{const link=kind.value==='link';fileWrap.hidden=link;urlWrap.hidden=!link;file.required=!link;dialog.querySelector('#ref-url').required=link;file.accept=kind.value==='image'?'image/*':kind.value==='video'?'video/*':'*/*'});
  document.querySelector('#open-upload').addEventListener('click',()=>dialog.showModal());dialog.querySelector('.icon-btn').addEventListener('click',()=>dialog.close());
  dialog.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),value={id:crypto.randomUUID(),kind:f.get('kind'),title:f.get('title'),notes:f.get('notes'),url:f.get('url'),file:f.get('file'),created:Date.now()};await putRef(value);dialog.close();e.currentTarget.reset();kind.dispatchEvent(new Event('change'));renderRefs()});renderRefs();
}
